  const claim=id=>{const current=tasks.find(task=>task.id===id);if(!current||current.status!=="reported")return notify(t("alreadyClaimed"));setTasks(items=>items.map(task=>task.id===id?{...task,status:"assigned",assignee:me.name,acceptedBy:me.name,avatar:me.avatar,acceptedAt:Date.now()}:task));setSection("current");notify(t("claimedSuccess"));};
