  const finish=id=>{if(!cause||!note.trim())return notify(t("resultRequired"));setTasks(current=>current.map(task=>task.id===id&&task.status==="repairing"?{...task,status:"acceptance",repairCompletedAt:Date.now(),result:{causeKey:cause,note:note.trim(),photo,photos:photo?[photo]:[]}}:task));setCause("");setNote("");setPhoto("");notify(t("handoverSuccess"));};
  const transfer=tech=>{const task=tasks.find(item=>item.id===transferTaskId);if(!task||task.assignee!==me.name||!["assigned","repairing"].includes(task.status)){setTransferTaskId("");return notify(t("transferUnavailable"));}const at=Date.now();setTasks(current=>current.map(item=>item.id===task.id?{...item,acceptedBy:item.acceptedBy||me.name,assignee:tech.name,avatar:tech.avatar,transfers:[...(item.transfers||[]),{from:me.name,to:tech.name,at}]}:item));setTransferTaskId("");setSelectedId("");notify(`${t("transferSuccess")} ${tech.name}`);};
  const reportProblem=task=>{if(!task)return notify(t("selectOrderFirst"));setTasks(current=>current.map(item=>item.id===task.id?{...item,alerts:[...(item.alerts||[]),{by:me.name,at:Date.now()}]}:item));notify(t("problemReported"));};
  const navigationActions=[{key:"available",label:t("navAvailable"),Icon:UsersThree,onClick:()=>setSection("available")},{key:"current",label:t("navCurrent"),Icon:Wrench,onClick:()=>setSection("current"),primary:true}];
  if(section==="history")return <WorkerOrdersPage items={history} title={t("historyTitle")} t={t} lang={lang} now={now} emptyHint={t("emptyHistory")} focusTaskId={focusTaskId} actionFactory={()=>navigationActions}/>;
  if(section==="equipment")return <><EquipmentView tasks={tasks} t={t}/><PersistentActionBar actions={navigationActions} t={t}/></>;
  if(section==="settings")return <><Settings t={t} lang={lang} setLang={setLang}/><PersistentActionBar actions={navigationActions} t={t}/></>;
  const taskActions=selected?[{key:"problem",label:t("reportProblem"),Icon:WarningCircle,onClick:()=>reportProblem(selected),danger:true},selected.assignee===me.name&&["assigned","repairing"].includes(selected.status)?{key:"transfer",label:t("transferOrder"),Icon:ArrowsLeftRight,onClick:()=>setTransferTaskId(selected.id)}:null,selected.status==="reported"?{key:"claim",label:t("claim"),Icon:UserPlus,onClick:()=>claim(selected.id),primary:true}:selected.status==="assigned"?{key:"start",label:t("startRepair"),Icon:Play,onClick:()=>start(selected.id),primary:true}:selected.status==="repairing"?{key:"finish",label:t("finishAction"),Icon:CheckCircle,onClick:()=>finish(selected.id),primary:true,disabled:!cause||!note.trim()}:null]:[{key:"refresh",label:t("refreshData"),Icon:ArrowsClockwise,onClick:()=>notify(t("refreshDone")),primary:true}];
  return <><main className="worker-page"><div className="worker-heading technician-heading"><img src={me.avatar} alt=""/><div><h1>{t("technicianTitle")}</h1><p>{t("technicianSub")}</p></div><div className="technician-meta"><span className="update-chip"><ArrowsClockwise size={16}/><span>{t("updatedAt")}</span><strong>{clockWithSeconds(updatedAt,lang)}</strong></span><span className="available-chip"><i/>{me.name}</span></div></div><div className="technician-shell"><aside className="tech-list"><div className="list-section-title"><strong>{t(section==="available"?"navAvailable":"navCurrent")}</strong><span>{list.length}</span></div><TaskList tasks={list} selectedId={selected?.id} onSelect={setSelectedId} t={t} lang={lang} now={now} emptyHint={t(section==="available"?"noAvailable":"noMine")}/></aside><section className="tech-detail">{selected?<><div className="tech-machine"><span><Factory size={34}/></span><div><h2>{selected.machineId} · {t(selected.machineKey)}</h2><p><MapPin size={16}/>{selected.location}</p></div><div className="tech-task-actions"><StatusBadge task={selected} t={t}/></div></div><SlaIndicator task={selected} now={now} t={t} lang={lang}/><div className="fault-callout"><WarningCircle size={22}/><div><small>{t("fault")}</small><strong>{t(selected.issueKey)}</strong>{selected.note&&<p>{selected.note}</p>}</div></div><DurationStrip task={selected} now={now} t={t} lang={lang}/><EvidencePreview task={selected} t={t}/><RecentMachineHistory task={selected} tasks={tasks} now={now} t={t} lang={lang}/>
    {selected.status==="reported"&&<div className="claim-zone"><p><UsersThree size={19}/>{t("broadcast")}</p></div>}{selected.status==="assigned"&&<div className="claim-zone"><p><MapPin size={19}/>{t("goToMachine")}</p></div>}{selected.status==="repairing"&&<div className="repair-form"><h3><Wrench size={21}/>{t("submitResult")}</h3><label><span>{t("resultCategory")}</span><select value={cause} onChange={e=>setCause(e.target.value)}><option value="">—</option>{causes.map(key=><option key={key} value={key}>{t(key)}</option>)}</select></label><label><span>{t("resultNote")}</span><textarea value={note} onChange={e=>setNote(e.target.value)} placeholder={t("resultPlaceholder")} maxLength={300}/></label><TechnicianPhotoInput label={t("resultPhoto")} hint={t("technicianPhotoHint")} value={photo} onChange={setPhoto} t={t}/></div>}{selected.status==="acceptance"&&<div className="waiting-acceptance"><CheckCircle size={31}/><strong>{t("statusAcceptance")}</strong><p>{t("handoverSuccess")}</p></div>}</>:<div className="detail-empty"><Wrench size={38}/><strong>{t(section==="available"?"noAvailable":"noMine")}</strong></div>}</section></div></main><PersistentActionBar actions={taskActions} t={t}/><TransferDialog task={tasks.find(task=>task.id===transferTaskId)} tasks={tasks} onTransfer={transfer} onClose={()=>setTransferTaskId("")} t={t}/></>;
