export function App(){
  const [tasks,setTasks]=useState(readTasks),[role,setRole]=useState(()=>localStorage.getItem("m4-role")||"admin"),[lang,setLang]=useState(()=>localStorage.getItem("m4-lang")||"zh"),[now,setNow]=useState(Date.now()),[updatedAt,setUpdatedAt]=useState(Date.now()),[toast,setToast]=useState("");
  const [sections,setSections]=useState({admin:"exceptions",operator:"report",technician:"available"});
  const [focusTaskId,setFocusTaskId]=useState(""),[menuOpen,setMenuOpen]=useState(false);
  const t=key=>copy[lang]?.[key]||copy.en[key]||key;
  useEffect(()=>{const timer=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(timer);},[]);useEffect(()=>{const serialized=JSON.stringify(tasks);if(localStorage.getItem(STORAGE_KEY)!==serialized)localStorage.setItem(STORAGE_KEY,serialized);setUpdatedAt(Date.now());},[tasks]);useEffect(()=>{const sync=event=>{if(event.key!==STORAGE_KEY||!event.newValue)return;try{const next=JSON.parse(event.newValue);if(Array.isArray(next))setTasks(next);}catch{}};window.addEventListener("storage",sync);return()=>window.removeEventListener("storage",sync);},[]);useEffect(()=>localStorage.setItem("m4-role",role),[role]);useEffect(()=>{localStorage.setItem("m4-lang",lang);document.documentElement.lang=lang==="zh"?"zh-CN":lang==="bm"?"ms":"en";},[lang]);
  const notify=message=>{setToast(message);clearTimeout(window.__m4ToastTimer);window.__m4ToastTimer=setTimeout(()=>setToast(""),3000);};
  const section=sections[role];
  const setSection=next=>setSections(current=>({...current,[role]:next}));
  const alertCount=tasks.filter(task=>getException(task,now)).length;
  const openSearchTask=task=>{setFocusTaskId(task.id);const target=role==="admin"?(task.status==="closed"?"history":getException(task,Date.now())?"exceptions":"live"):role==="operator"?(task.status==="closed"?"history":"current"):(task.status==="closed"?"history":task.status==="reported"?"available":"current");setSections(current=>({...current,[role]:target}));};
  const workerContent=role==="operator"?<OperatorApp tasks={tasks} setTasks={setTasks} now={now} t={t} lang={lang} notify={notify} section={section} setSection={setSection} setLang={setLang} focusTaskId={focusTaskId}/>:<TechnicianApp tasks={tasks} setTasks={setTasks} now={now} updatedAt={updatedAt} t={t} lang={lang} notify={notify} section={section} setSection={setSection} setLang={setLang} focusTaskId={focusTaskId}/>;
  return <div className={`app-shell ${role!=="admin"?"has-action-bar":alertCount>0?"has-admin-action-bar":""}`}><Header role={role} setRole={setRole} lang={lang} setLang={setLang} t={t} tasks={tasks} onSearchNavigate={openSearchTask} onMenuOpen={()=>setMenuOpen(true)} alertCount={alertCount}/><MobileMenu open={menuOpen} role={role} section={section} setSection={setSection} setRole={setRole} onClose={()=>setMenuOpen(false)} t={t} alertCount={alertCount}/>{role==="admin"?<AdminApp tasks={tasks} setTasks={setTasks} now={now} t={t} lang={lang} notify={notify} setLang={setLang} section={section} setSection={setSection} setRole={setRole} focusTaskId={focusTaskId}/>:<div className="role-layout"><PortalSidebar role={role} section={section} setSection={setSection} setRole={setRole} t={t}/><div className="role-main worker-main">{workerContent}</div></div>}{toast&&<div className="toast" role="status"><CheckCircle size={19} weight="fill"/>{toast}</div>}</div>;
}
